import fs from 'node:fs'
import path from 'node:path'

const distDir = path.resolve('dist')
const stylesheetTag = '<?xml-stylesheet type="text/xsl" href="/sitemap.xsl"?>\n'

if (fs.existsSync(distDir)) {
  // Find all sitemap XML files generated by @astrojs/sitemap
  const sitemapFiles = fs
    .readdirSync(distDir)
    .filter((file) => file.startsWith('sitemap') && file.endsWith('.xml'))

  sitemapFiles.forEach((file) => {
    const filePath = path.join(distDir, file)
    let xmlContent = fs.readFileSync(filePath, 'utf8')

    // Inject stylesheet tag if not already present
    if (!xmlContent.includes('xml-stylesheet')) {
      xmlContent = xmlContent.replace(
        '<?xml version="1.0" encoding="UTF-8"?>',
        `<?xml version="1.0" encoding="UTF-8"?>\n${stylesheetTag}`,
      )
      fs.writeFileSync(filePath, xmlContent, 'utf8')
      console.log(`[sitemap] Injected sitemap.xsl into dist/${file}`)
    }
  })
} else {
  console.error('[sitemap] dist/ directory not found.')
}
